    case "decoding": self = .decoding
    case "busy": self = .busy
    case "timedOut": self = .timedOut
    case "invalidRequest": self = .invalidRequest
    case "invalidSchema": self = .invalidSchema
    case "invalidToolSchema": self = .invalidToolSchema
    case "invalidStream": self = .invalidStream
    case "unavailable": self = .unavailable
    case "failed": self = .failed
    default: self = .unknown(rawValue)
    }
  }

  /// The value as it goes on the wire.
  public var rawValue: String {
    switch self {
    case .contextExceeded: return "contextExceeded"
    case .notReady: return "notReady"
    case .guardrail: return "guardrail"
    case .refusal: return "refusal"
    case .unsupported: return "unsupported"
    case .decoding: return "decoding"
    case .busy: return "busy"
    case .timedOut: return "timedOut"
    case .invalidRequest: return "invalidRequest"
    case .invalidSchema: return "invalidSchema"
    case .invalidToolSchema: return "invalidToolSchema"
    case .invalidStream: return "invalidStream"
    case .unavailable: return "unavailable"
