/// Mirrors the core's `AuthStatus` one-for-one.
///
/// Repeated rather than shared because `conduit_core` cannot cross into the
/// renderer -- it reaches `dart:io`. Adding a case to one without the other
/// is caught by the exhaustive switch in the daemon's mapper, which is the
/// point of keeping it an enum on both sides.
public enum AuthPhase: Codable, Hashable, Sendable {
  /// Nothing has been attempted yet this launch.
  case initial
  case loading
  case authenticated
  case unauthenticated
  /// A token existed and is no longer accepted -- distinct from never having
  /// had one, because the UI offers "sign in again" rather than onboarding.
  case tokenExpired
  case error
  /// The credentials themselves were rejected, so retrying the same ones is
  /// pointless and the form says so.
  case credentialError
  /// A value this build does not know, from a newer core, kept as it came.
  case unknown(String)

  public init(rawValue: String) {
    switch rawValue {
    case "initial": self = .initial
    case "loading": self = .loading
    case "authenticated": self = .authenticated
    case "unauthenticated": self = .unauthenticated
    case "tokenExpired": self = .tokenExpired
    case "error": self = .error
    case "credentialError": self = .credentialError
    default: self = .unknown(rawValue)
    }
  }

  /// The value as it goes on the wire.
  public var rawValue: String {
    switch self {
    case .initial: return "initial"
    case .loading: return "loading"
    case .authenticated: return "authenticated"
    case .unauthenticated: return "unauthenticated"
    case .tokenExpired: return "tokenExpired"
    case .error: return "error"
    case .credentialError: return "credentialError"
    case .unknown(let raw): return raw
    }
  }

  public init(from decoder: Decoder) throws {
    self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.singleValueContainer()
    try container.encode(rawValue)
  }
}

/// The renderer's view of the session.
///
/// Carries no token. The renderer never holds one: every authenticated
/// request is made by the daemon, which is what lets the token live in the
/// secure store and nowhere else.
public struct AuthSnapshot: Codable, Equatable, Sendable {
  public var phase: AuthPhase
  public var isAuthenticated: Bool
  public var isLoading: Bool
  /// True when a token is held daemon-side. The UI uses this to tell
  /// "signed in" from "signing in".
  public var hasToken: Bool
  public var user: AuthUser?
  /// Set when [phase] is `error` or `credentialError`. A code plus args,
  /// localized in the UI -- never server prose, which would arrive in the
  /// server's locale rather than the user's.
  public var errorCode: String?
  public var errorArgs: [String: String]
  /// True when the reviewer/demo path is active: the UI runs against
  /// canned models and conversations with no server at all.
  public var isReviewerMode: Bool
  /// Set while a password or LDAP sign-in waits on its second step
  /// (`auth.twoStep.*`): the password was right, and the server asks for
  /// an authenticator code before it issues a session.
  public var twoStep: TwoStepChallenge?
  /// The active server is reached through a reverse proxy whose session
  /// cookie the account keeps, so an expired proxy session can be signed
  /// in to again in place (`auth.renewProxy`) rather than signed out of.
  public var canRenewProxy: Bool

  public init(
    phase: AuthPhase,
    isAuthenticated: Bool = false,
    isLoading: Bool = false,
    hasToken: Bool = false,
    user: AuthUser? = nil,
    errorCode: String? = nil,
    errorArgs: [String: String] = [:],
    isReviewerMode: Bool = false,
    twoStep: TwoStepChallenge? = nil,
    canRenewProxy: Bool = false
  ) {
    self.phase = phase
    self.isAuthenticated = isAuthenticated
    self.isLoading = isLoading
    self.hasToken = hasToken
    self.user = user
    self.errorCode = errorCode
    self.errorArgs = errorArgs
    self.isReviewerMode = isReviewerMode
    self.twoStep = twoStep
    self.canRenewProxy = canRenewProxy
  }

  private enum CodingKeys: String, CodingKey {
    case phase
    case isAuthenticated
    case isLoading
    case hasToken
    case user
    case errorCode
    case errorArgs
    case isReviewerMode
    case twoStep
    case canRenewProxy
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)
    self.phase = try container.decode(AuthPhase.self, forKey: .phase)
    self.isAuthenticated = try container.decodeIfPresent(Bool.self, forKey: .isAuthenticated) ?? false
    self.isLoading = try container.decodeIfPresent(Bool.self, forKey: .isLoading) ?? false
    self.hasToken = try container.decodeIfPresent(Bool.self, forKey: .hasToken) ?? false
    self.user = try container.decodeIfPresent(AuthUser.self, forKey: .user)
    self.errorCode = try container.decodeIfPresent(String.self, forKey: .errorCode)
    self.errorArgs = try container.decodeIfPresent([String: String].self, forKey: .errorArgs) ?? [:]
    self.isReviewerMode = try container.decodeIfPresent(Bool.self, forKey: .isReviewerMode) ?? false
    self.twoStep = try container.decodeIfPresent(TwoStepChallenge.self, forKey: .twoStep)
    self.canRenewProxy = try container.decodeIfPresent(Bool.self, forKey: .canRenewProxy) ?? false
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: CodingKeys.self)
    try container.encode(self.phase, forKey: .phase)
    try container.encode(self.isAuthenticated, forKey: .isAuthenticated)
    try container.encode(self.isLoading, forKey: .isLoading)
    try container.encode(self.hasToken, forKey: .hasToken)
    try container.encodeIfPresent(self.user, forKey: .user)
    try container.encodeIfPresent(self.errorCode, forKey: .errorCode)
    try container.encode(self.errorArgs, forKey: .errorArgs)
    try container.encode(self.isReviewerMode, forKey: .isReviewerMode)
    try container.encodeIfPresent(self.twoStep, forKey: .twoStep)
    try container.encode(self.canRenewProxy, forKey: .canRenewProxy)
  }
}

