/// One piece of rich content in an answer or a tool call's result.
public struct EmbedDto: Codable, Equatable, Sendable {
  public var kind: EmbedKind
  /// [EmbedKind.html]: the markup. [EmbedKind.url]: the address.
  public var source: String?
  /// A tool call's arguments as written, which an HTML embed may read as
  /// `window.args`; empty for an answer's own embeds.
  public var argsText: String
  /// [EmbedKind.mcpApp]: the app, to open with `mcpApps.open`.
  public var app: McpAppDto?

  public init(
    kind: EmbedKind,
    source: String? = nil,
    argsText: String = "",
    app: McpAppDto? = nil
  ) {
    self.kind = kind
    self.source = source
    self.argsText = argsText
    self.app = app
  }

  private enum CodingKeys: String, CodingKey {
    case kind
    case source
    case argsText
    case app
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)
    self.kind = try container.decode(EmbedKind.self, forKey: .kind)
    self.source = try container.decodeIfPresent(String.self, forKey: .source)
    self.argsText = try container.decodeIfPresent(String.self, forKey: .argsText) ?? ""
    self.app = try container.decodeIfPresent(McpAppDto.self, forKey: .app)
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: CodingKeys.self)
    try container.encode(self.kind, forKey: .kind)
    try container.encodeIfPresent(self.source, forKey: .source)
    try container.encode(self.argsText, forKey: .argsText)
    try container.encodeIfPresent(self.app, forKey: .app)
  }
}

/// What a reasoning block's header reads.
public enum ReasoningTitle: Codable, Hashable, Sendable {
  /// "Thinking…": not done yet.
  case thinking
  /// "Thought for N seconds", N being [MessageBlockDto.durationSeconds].
  case thoughtFor
  /// The block's own [MessageBlockDto.summary].
  case summary
  /// "Thoughts": done, with no timing.
  case thoughts
  /// A value this build does not know, from a newer core, kept as it came.
  case unknown(String)

  public init(rawValue: String) {
    switch rawValue {
    case "thinking": self = .thinking
    case "thoughtFor": self = .thoughtFor
    case "summary": self = .summary
    case "thoughts": self = .thoughts
    default: self = .unknown(rawValue)
    }
  }

  /// The value as it goes on the wire.
  public var rawValue: String {
    switch self {
    case .thinking: return "thinking"
    case .thoughtFor: return "thoughtFor"
    case .summary: return "summary"
    case .thoughts: return "thoughts"
    case .unknown(let raw): return raw
    }
  }

  public init(from decoder: Decoder) throws {
    self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.singleValueContainer()
    try container.encode(rawValue)
  }
}

/// One block of an assistant answer, already parsed by the daemon.
///
/// One flat record for every [MessageBlockKind]: [kind] says which fields
/// are set, and the rest are left out. Markdown fields ([markdown], [body],
/// and [output] of a code-interpreter run) are written for a plain markdown
/// renderer (CommonMark + GFM + `$` math): prose dollars are escaped, math
/// is `$…$` or a `$$` block, raw HTML is escaped, and a citation `[n]` is a
/// link to `conduit-cite:n`. Code, tool arguments and results are as
/// written.
public struct MessageBlockDto: Codable, Equatable, Sendable {
  public var kind: MessageBlockKind
  /// `text`: the markdown. `alert`: its body, as markdown.
  public var markdown: String?
  /// `reasoning`, `details`: the `<summary>` text (may be empty).
  /// `status`: what a run of Hermes tools did (`terminal (2), search`),
  /// for the row's own "Exploring …" or "Explored …".
  public var summary: String?
  /// `reasoning`: what the header reads.
  public var title: ReasoningTitle?
  /// `reasoning`: the seconds a [ReasoningTitle.thoughtFor] header reads
  /// (the section's duration, or the timing an older answer kept only in
  /// its summary); otherwise the duration, when the section has one.
  public var durationSeconds: Int?
  /// `reasoning`, `codeInterpreter`, `details`, `codeExecution`: finished.
  public var done: Bool?
  /// `reasoning`, `codeInterpreter`, `details`, `codeExecution`: not
  /// finished, and says so -- show a spinner. `status`: the row shimmers.
  public var pending: Bool?
  /// `reasoning`, `details`: the section's markdown.
  public var body: String?
  /// `toolCalls`: the calls, in order.
  public var calls: [ToolCallDto]?
  /// `codeInterpreter`, `codeExecution`: the code.
  public var code: String?
  /// `codeInterpreter`, `codeExecution`: its language (`python`, …); may
  /// be empty.
  public var language: String?
  /// `codeInterpreter`: the run's output, as markdown.
  /// `codeExecution`: its output, as plain text.
  public var output: String?
  /// `codeExecution`: the execution's id.
  public var id: String?
  /// `codeExecution`: its name, when it has one (hosts say "Execution"
  /// otherwise).
  public var name: String?
  /// `codeExecution`: the error it ended with, as plain text.
  /// `error`: the server's or provider's words, as plain text; empty when
  /// it gave none.
  public var error: String?
  /// `codeExecution`: it ended with [error].
  public var isError: Bool?
  /// `details`: the section's `type` attribute; empty when absent.
  /// `alert`: its kind (`note`, `tip`, `important`, `warning`,
  /// `caution`).
  /// `error`: why, when hosts should say something other than [error]:
  /// `directToolsUnsupported` (the model refused tool definitions; advise
  /// turning web search off), `heldReplyStillRunning` (a polling-only
  /// server may still be writing the reply; open the chat again later),
  /// and a failed relay to one of the user's Tether devices:
  /// `tetherInterrupted` (it may have run; check before repeating it),
  /// `tetherUnavailable`, `tetherBusy`. Absent otherwise.
  public var type: String?
  /// `status`: the timeline, oldest first.
  public var statuses: [MessageStatusDto]?
  /// `files`: the answer's files. `codeExecution`: files it wrote.
  public var files: [ChatFileDto]?
  /// `sources`: what `[n]` cites, in order.
  public var sources: [ChatSourceDto]?
  /// `followUps`: the suggestions.
  public var followUps: [String]?
  /// `embeds`: what the answer carries, in order.
  public var embeds: [EmbedDto]?
  /// `changedFiles`: each changed file, in the order the tools changed
  /// them.
  public var changedFiles: [ChangedFileDto]?
  /// `error`: a Hermes failure as Hermes classified it, for its card.
  public var hermesError: HermesErrorDto?

  public init(
    kind: MessageBlockKind,
    markdown: String? = nil,
    summary: String? = nil,
    title: ReasoningTitle? = nil,
    durationSeconds: Int? = nil,
    done: Bool? = nil,
    pending: Bool? = nil,
    body: String? = nil,
    calls: [ToolCallDto]? = nil,
    code: String? = nil,
    language: String? = nil,
    output: String? = nil,
    id: String? = nil,
    name: String? = nil,
    error: String? = nil,
    isError: Bool? = nil,
    type: String? = nil,
    statuses: [MessageStatusDto]? = nil,
    files: [ChatFileDto]? = nil,
    sources: [ChatSourceDto]? = nil,
    followUps: [String]? = nil,
    embeds: [EmbedDto]? = nil,
    changedFiles: [ChangedFileDto]? = nil,
    hermesError: HermesErrorDto? = nil
  ) {
    self.kind = kind
    self.markdown = markdown
    self.summary = summary
    self.title = title
    self.durationSeconds = durationSeconds
    self.done = done
    self.pending = pending
    self.body = body
    self.calls = calls
    self.code = code
    self.language = language
    self.output = output
    self.id = id
    self.name = name
    self.error = error
    self.isError = isError
    self.type = type
    self.statuses = statuses
    self.files = files
    self.sources = sources
    self.followUps = followUps
    self.embeds = embeds
    self.changedFiles = changedFiles
    self.hermesError = hermesError
  }

  private enum CodingKeys: String, CodingKey {
    case kind
    case markdown
    case summary
    case title
    case durationSeconds
    case done
    case pending
    case body
    case calls
    case code
    case language
    case output
    case id
    case name
    case error
    case isError
    case type
    case statuses
    case files
    case sources
    case followUps
    case embeds
    case changedFiles
    case hermesError
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)
    self.kind = try container.decode(MessageBlockKind.self, forKey: .kind)
    self.markdown = try container.decodeIfPresent(String.self, forKey: .markdown)
    self.summary = try container.decodeIfPresent(String.self, forKey: .summary)
    self.title = try container.decodeIfPresent(ReasoningTitle.self, forKey: .title)
    self.durationSeconds = try container.decodeIfPresent(Int.self, forKey: .durationSeconds)
    self.done = try container.decodeIfPresent(Bool.self, forKey: .done)
    self.pending = try container.decodeIfPresent(Bool.self, forKey: .pending)
    self.body = try container.decodeIfPresent(String.self, forKey: .body)
    self.calls = try container.decodeIfPresent([ToolCallDto].self, forKey: .calls)
    self.code = try container.decodeIfPresent(String.self, forKey: .code)
    self.language = try container.decodeIfPresent(String.self, forKey: .language)
    self.output = try container.decodeIfPresent(String.self, forKey: .output)
    self.id = try container.decodeIfPresent(String.self, forKey: .id)
    self.name = try container.decodeIfPresent(String.self, forKey: .name)
    self.error = try container.decodeIfPresent(String.self, forKey: .error)
    self.isError = try container.decodeIfPresent(Bool.self, forKey: .isError)
    self.type = try container.decodeIfPresent(String.self, forKey: .type)
    self.statuses = try container.decodeIfPresent([MessageStatusDto].self, forKey: .statuses)
    self.files = try container.decodeIfPresent([ChatFileDto].self, forKey: .files)
    self.sources = try container.decodeIfPresent([ChatSourceDto].self, forKey: .sources)
    self.followUps = try container.decodeIfPresent([String].self, forKey: .followUps)
    self.embeds = try container.decodeIfPresent([EmbedDto].self, forKey: .embeds)
    self.changedFiles = try container.decodeIfPresent([ChangedFileDto].self, forKey: .changedFiles)
    self.hermesError = try container.decodeIfPresent(HermesErrorDto.self, forKey: .hermesError)
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: CodingKeys.self)
    try container.encode(self.kind, forKey: .kind)
    try container.encodeIfPresent(self.markdown, forKey: .markdown)
    try container.encodeIfPresent(self.summary, forKey: .summary)
    try container.encodeIfPresent(self.title, forKey: .title)
    try container.encodeIfPresent(self.durationSeconds, forKey: .durationSeconds)
    try container.encodeIfPresent(self.done, forKey: .done)
    try container.encodeIfPresent(self.pending, forKey: .pending)
    try container.encodeIfPresent(self.body, forKey: .body)
    try container.encodeIfPresent(self.calls, forKey: .calls)
    try container.encodeIfPresent(self.code, forKey: .code)
    try container.encodeIfPresent(self.language, forKey: .language)
    try container.encodeIfPresent(self.output, forKey: .output)
    try container.encodeIfPresent(self.id, forKey: .id)
    try container.encodeIfPresent(self.name, forKey: .name)
    try container.encodeIfPresent(self.error, forKey: .error)
    try container.encodeIfPresent(self.isError, forKey: .isError)
    try container.encodeIfPresent(self.type, forKey: .type)
    try container.encodeIfPresent(self.statuses, forKey: .statuses)
    try container.encodeIfPresent(self.files, forKey: .files)
    try container.encodeIfPresent(self.sources, forKey: .sources)
    try container.encodeIfPresent(self.followUps, forKey: .followUps)
    try container.encodeIfPresent(self.embeds, forKey: .embeds)
    try container.encodeIfPresent(self.changedFiles, forKey: .changedFiles)
    try container.encodeIfPresent(self.hermesError, forKey: .hermesError)
  }
}

/// One tool call in a `toolCalls` block.
public struct ToolCallDto: Codable, Equatable, Sendable {
  /// The call's id; may be empty.
  public var id: String
  /// The tool's name; may be empty (hosts say "tool").
  public var name: String
  /// The arguments as written, usually a JSON object; empty when none.
  public var arguments: String
  /// The result as written: JSON, a JSON string or plain text; empty
  /// until it has one.
  public var result: String
  /// Finished, or ended (failed, rejected, incomplete).
  public var done: Bool
  /// Not finished, and says so: show a spinner.
  public var pending: Bool
  /// Open WebUI's approval status (`pending`, `completed`, `failed`,
  /// `rejected`, `incomplete`, …), when it has one.
  public var status: String?
  /// The call failed, or its result reads as an error.
  public var isError: Bool
  /// Files the tool returned, as the JSON array Open WebUI wrote.
  public var files: String?
  /// Embeds the tool returned, as the JSON array Open WebUI wrote.
  public var embeds: String?
  /// [embeds], read: what to show under the call, in order (HTML with
  /// the call's arguments, a page, or an MCP App).
  public var shownEmbeds: [EmbedDto]

  public init(
    id: String = "",
    name: String = "",
    arguments: String = "",
    result: String = "",
    done: Bool = false,
    pending: Bool = false,
    status: String? = nil,
    isError: Bool = false,
    files: String? = nil,
    embeds: String? = nil,
    shownEmbeds: [EmbedDto] = []
  ) {
    self.id = id
    self.name = name
    self.arguments = arguments
    self.result = result
    self.done = done
    self.pending = pending
    self.status = status
    self.isError = isError
    self.files = files
    self.embeds = embeds
    self.shownEmbeds = shownEmbeds
  }

  private enum CodingKeys: String, CodingKey {
    case id
    case name
    case arguments
    case result
    case done
    case pending
    case status
    case isError
    case files
    case embeds
    case shownEmbeds
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)
    self.id = try container.decodeIfPresent(String.self, forKey: .id) ?? ""
    self.name = try container.decodeIfPresent(String.self, forKey: .name) ?? ""
    self.arguments = try container.decodeIfPresent(String.self, forKey: .arguments) ?? ""
    self.result = try container.decodeIfPresent(String.self, forKey: .result) ?? ""
    self.done = try container.decodeIfPresent(Bool.self, forKey: .done) ?? false
    self.pending = try container.decodeIfPresent(Bool.self, forKey: .pending) ?? false
    self.status = try container.decodeIfPresent(String.self, forKey: .status)
    self.isError = try container.decodeIfPresent(Bool.self, forKey: .isError) ?? false
    self.files = try container.decodeIfPresent(String.self, forKey: .files)
    self.embeds = try container.decodeIfPresent(String.self, forKey: .embeds)
    self.shownEmbeds = try container.decodeIfPresent([EmbedDto].self, forKey: .shownEmbeds) ?? []
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: CodingKeys.self)
    try container.encode(self.id, forKey: .id)
    try container.encode(self.name, forKey: .name)
    try container.encode(self.arguments, forKey: .arguments)
    try container.encode(self.result, forKey: .result)
    try container.encode(self.done, forKey: .done)
    try container.encode(self.pending, forKey: .pending)
    try container.encodeIfPresent(self.status, forKey: .status)
    try container.encode(self.isError, forKey: .isError)
    try container.encodeIfPresent(self.files, forKey: .files)
    try container.encodeIfPresent(self.embeds, forKey: .embeds)
    try container.encode(self.shownEmbeds, forKey: .shownEmbeds)
  }
}

/// The status lines core words itself (the core's `ChatStatusPhrase`).
public enum StatusPhrase: Codable, Hashable, Sendable {
  /// "Searching Knowledge for "…"", with [MessageStatusDto.query].
  case knowledgeSearch
  case searching
  case querying
  /// "Retrieved N sources", with [MessageStatusDto.count].
  case sourcesRetrieved
  case processing
  /// A value this build does not know, from a newer core, kept as it came.
  case unknown(String)

  public init(rawValue: String) {
    switch rawValue {
    case "knowledgeSearch": self = .knowledgeSearch
    case "searching": self = .searching
    case "querying": self = .querying
    case "sourcesRetrieved": self = .sourcesRetrieved
    case "processing": self = .processing
    default: self = .unknown(rawValue)
    }
  }

  /// The value as it goes on the wire.
  public var rawValue: String {
    switch self {
    case .knowledgeSearch: return "knowledgeSearch"
    case .searching: return "searching"
    case .querying: return "querying"
    case .sourcesRetrieved: return "sourcesRetrieved"
    case .processing: return "processing"
    case .unknown(let raw): return raw
    }
  }

  public init(from decoder: Decoder) throws {
    self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.singleValueContainer()
    try container.encode(rawValue)
  }
}

/// One line of a `status` block's timeline.
public struct MessageStatusDto: Codable, Equatable, Sendable {
  /// What the line reads, worded as Open WebUI's client words it.
  public var description: String
  /// When [description] is core's own wording rather than Open WebUI's:
  /// which, for the window to word in its own language.
  public var phrase: StatusPhrase?
  /// How many sources `sourcesRetrieved` found.
  public var count: Int?
  /// What `knowledgeSearch` searched for.
  public var query: String?
  /// The update's action (`web_search`, `knowledge_search`, …), if any.
  public var action: String?
  /// The update reported done.
  public var done: Bool
  /// Search queries it ran.
  public var queries: [String]
  /// Pages it found. [ChatSourceDto.label] is the page's title, or its
  /// domain.
  public var links: [ChatSourceDto]
  /// Items to show as a snippet under a title: [ChatSourceDto.label] and
  /// [ChatSourceDto.snippet].
  public var details: [ChatSourceDto]

  public init(
    description: String,
    phrase: StatusPhrase? = nil,
    count: Int? = nil,
    query: String? = nil,
    action: String? = nil,
    done: Bool = false,
    queries: [String] = [],
    links: [ChatSourceDto] = [],
    details: [ChatSourceDto] = []
  ) {
    self.description = description
    self.phrase = phrase
    self.count = count
    self.query = query
    self.action = action
    self.done = done
    self.queries = queries
    self.links = links
    self.details = details
  }

  private enum CodingKeys: String, CodingKey {
    case description
    case phrase
    case count
    case query
    case action
    case done
    case queries
    case links
    case details
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)
    self.description = try container.decode(String.self, forKey: .description)
    self.phrase = try container.decodeIfPresent(StatusPhrase.self, forKey: .phrase)
    self.count = try container.decodeIfPresent(Int.self, forKey: .count)
    self.query = try container.decodeIfPresent(String.self, forKey: .query)
    self.action = try container.decodeIfPresent(String.self, forKey: .action)
    self.done = try container.decodeIfPresent(Bool.self, forKey: .done) ?? false
    self.queries = try container.decodeIfPresent([String].self, forKey: .queries) ?? []
    self.links = try container.decodeIfPresent([ChatSourceDto].self, forKey: .links) ?? []
    self.details = try container.decodeIfPresent([ChatSourceDto].self, forKey: .details) ?? []
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: CodingKeys.self)
    try container.encode(self.description, forKey: .description)
    try container.encodeIfPresent(self.phrase, forKey: .phrase)
    try container.encodeIfPresent(self.count, forKey: .count)
    try container.encodeIfPresent(self.query, forKey: .query)
    try container.encodeIfPresent(self.action, forKey: .action)
    try container.encode(self.done, forKey: .done)
    try container.encode(self.queries, forKey: .queries)
    try container.encode(self.links, forKey: .links)
    try container.encode(self.details, forKey: .details)
  }
}

