}

/// One of the account's calendars on its Open WebUI server.
public struct CalendarDto: Codable, Equatable, Sendable {
  public var id: String
  public var name: String
  /// `#rrggbb` as the server stored it, or null.
  public var color: String?
  /// The account's own default calendar (a shared calendar's flag is its
  /// owner's and is not reported here).
  public var isDefault: Bool
  /// The server's read-only calendar of scheduled-task runs.
  public var scheduled: Bool
  /// The account owns it.
  public var owned: Bool
  /// Events can be created in it, moved into it and edited in it.
  public var writable: Bool
  /// It can be made the account's default (one of its own, not already).
  public var canMakeDefault: Bool
  /// The agenda shows its events.
  public var visible: Bool

  public init(
    id: String,
    name: String = "",
    color: String? = nil,
    isDefault: Bool = false,
    scheduled: Bool = false,
    owned: Bool = false,
    writable: Bool = false,
    canMakeDefault: Bool = false,
    visible: Bool = true
  ) {
    self.id = id
    self.name = name
    self.color = color
    self.isDefault = isDefault
    self.scheduled = scheduled
    self.owned = owned
    self.writable = writable
    self.canMakeDefault = canMakeDefault
    self.visible = visible
  }

  private enum CodingKeys: String, CodingKey {
    case id
    case name
    case color
    case isDefault
    case scheduled
    case owned
    case writable
    case canMakeDefault
    case visible
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)
    self.id = try container.decode(String.self, forKey: .id)
    self.name = try container.decodeIfPresent(String.self, forKey: .name) ?? ""
    self.color = try container.decodeIfPresent(String.self, forKey: .color)
    self.isDefault = try container.decodeIfPresent(Bool.self, forKey: .isDefault) ?? false
    self.scheduled = try container.decodeIfPresent(Bool.self, forKey: .scheduled) ?? false
    self.owned = try container.decodeIfPresent(Bool.self, forKey: .owned) ?? false
    self.writable = try container.decodeIfPresent(Bool.self, forKey: .writable) ?? false
    self.canMakeDefault = try container.decodeIfPresent(Bool.self, forKey: .canMakeDefault) ?? false
    self.visible = try container.decodeIfPresent(Bool.self, forKey: .visible) ?? true
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: CodingKeys.self)
    try container.encode(self.id, forKey: .id)
    try container.encode(self.name, forKey: .name)
    try container.encodeIfPresent(self.color, forKey: .color)
    try container.encode(self.isDefault, forKey: .isDefault)
