    self.shared = try container.decodeIfPresent(Bool.self, forKey: .shared) ?? false
    self.ownerName = try container.decodeIfPresent(String.self, forKey: .ownerName)
    self.canWrite = try container.decodeIfPresent(Bool.self, forKey: .canWrite) ?? true
