    modelName: String? = nil,
    streaming: Bool = false,
    errorCode: String? = nil,
    versions: [ChatMessageVersionDto] = [],
    sources: [ChatSourceDto] = [],
    usage: ChatUsageDto? = nil,
    rating: Int? = nil,
    files: [ChatFileDto] = [],
    blocks: [MessageBlockDto] = [],
    parentId: String? = nil,
    slot: Int? = nil,
    merged: String? = nil,
    retryWithoutEffort: Bool = false,
    comparison: [ComparisonSlotDto] = [],
    mergeableIds: [String] = [],
    siblingIds: [String] = [],
    queued: QueuedCompletionDto? = nil,
    held: Bool = false
  ) {
    self.id = id
    self.role = role
    self.content = content
    self.timestampMs = timestampMs
    self.model = model
    self.modelName = modelName
    self.streaming = streaming
    self.errorCode = errorCode
    self.versions = versions
    self.sources = sources
    self.usage = usage
    self.rating = rating
    self.files = files
    self.blocks = blocks
    self.parentId = parentId
