/// Reply to the `data.*` actions. [failure] is null when the action did what
/// it says, else core's reason, by name: for a backup or restore one of
/// `ChatBackupFailure` (`malformedExport`, `notJson`, `notAList`,
/// `emptyImport`, `fileTooLarge`, `unrecognizedChat`, `invalidField`,
/// `cancelled`, `ownerChanged`), for the rest one of
/// `ChatDataControlsFailure` (`forbidden`, `pendingWork`, `responseRunning`,
/// `localWorkChanged`, `serverRefused`, `outcomeUnknown`, `ownerChanged`,
/// `accountUnknown`), or `failed` for anything else.
public struct DataActionResult: Codable, Equatable, Sendable {
  public var failure: String?
  /// Chats exported, imported, or changed on this computer.
  public var count: Int
  /// For an import: of [count], those stored here already (the rest come
  /// with the next sync).
  public var stored: Int
  /// For an import's preview: the messages in the file's chats.
  public var messages: Int
  /// The 0-based position of the chat a restore refused, when it names one.
  public var index: Int?

  public init(
    failure: String? = nil,
    count: Int = 0,
    stored: Int = 0,
    messages: Int = 0,
    index: Int? = nil
  ) {
    self.failure = failure
    self.count = count
    self.stored = stored
    self.messages = messages
    self.index = index
  }

  private enum CodingKeys: String, CodingKey {
    case failure
    case count
    case stored
    case messages
    case index
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)
    self.failure = try container.decodeIfPresent(String.self, forKey: .failure)
    self.count = try container.decodeIfPresent(Int.self, forKey: .count) ?? 0
    self.stored = try container.decodeIfPresent(Int.self, forKey: .stored) ?? 0
    self.messages = try container.decodeIfPresent(Int.self, forKey: .messages) ?? 0
    self.index = try container.decodeIfPresent(Int.self, forKey: .index)
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: CodingKeys.self)
    try container.encodeIfPresent(self.failure, forKey: .failure)
    try container.encode(self.count, forKey: .count)
    try container.encode(self.stored, forKey: .stored)
    try container.encode(self.messages, forKey: .messages)
    try container.encodeIfPresent(self.index, forKey: .index)
  }
}

/// Reply to `data.connection`: the server's realtime socket, as core's
/// `SocketHealth` reports it. `socket.health` says when it changed.
public struct ConnectionHealth: Codable, Equatable, Sendable {
  /// An Open WebUI server's socket applies (none for Direct or Hermes).
  public var available: Bool
  public var connected: Bool
  /// `websocket`, `polling` or `unknown`.
  public var transport: String
  /// The last heartbeat's round trip, or null before one.
  public var latencyMs: Int?
  /// `excellent`, `good`, `fair`, `poor` or `unknown`.
  public var quality: String
  /// When the last heartbeat answered, in ms since the epoch.
  public var lastHeartbeatMs: Int?
  public var reconnects: Int
  /// The transports the server allows; Settings offers a choice only when
  /// it allows both.
  public var allowPolling: Bool
  public var allowWebsocket: Bool

  public init(
    available: Bool = false,
    connected: Bool = false,
    transport: String = "unknown",
    latencyMs: Int? = nil,
    quality: String = "unknown",
    lastHeartbeatMs: Int? = nil,
    reconnects: Int = 0,
    allowPolling: Bool = true,
    allowWebsocket: Bool = true
  ) {
    self.available = available
    self.connected = connected
    self.transport = transport
    self.latencyMs = latencyMs
    self.quality = quality
    self.lastHeartbeatMs = lastHeartbeatMs
    self.reconnects = reconnects
    self.allowPolling = allowPolling
    self.allowWebsocket = allowWebsocket
  }

  private enum CodingKeys: String, CodingKey {
    case available
    case connected
    case transport
    case latencyMs
    case quality
    case lastHeartbeatMs
    case reconnects
    case allowPolling
    case allowWebsocket
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)
    self.available = try container.decodeIfPresent(Bool.self, forKey: .available) ?? false
    self.connected = try container.decodeIfPresent(Bool.self, forKey: .connected) ?? false
    self.transport = try container.decodeIfPresent(String.self, forKey: .transport) ?? "unknown"
    self.latencyMs = try container.decodeIfPresent(Int.self, forKey: .latencyMs)
    self.quality = try container.decodeIfPresent(String.self, forKey: .quality) ?? "unknown"
    self.lastHeartbeatMs = try container.decodeIfPresent(Int.self, forKey: .lastHeartbeatMs)
    self.reconnects = try container.decodeIfPresent(Int.self, forKey: .reconnects) ?? 0
    self.allowPolling = try container.decodeIfPresent(Bool.self, forKey: .allowPolling) ?? true
    self.allowWebsocket = try container.decodeIfPresent(Bool.self, forKey: .allowWebsocket) ?? true
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: CodingKeys.self)
    try container.encode(self.available, forKey: .available)
    try container.encode(self.connected, forKey: .connected)
    try container.encode(self.transport, forKey: .transport)
    try container.encodeIfPresent(self.latencyMs, forKey: .latencyMs)
    try container.encode(self.quality, forKey: .quality)
    try container.encodeIfPresent(self.lastHeartbeatMs, forKey: .lastHeartbeatMs)
    try container.encode(self.reconnects, forKey: .reconnects)
    try container.encode(self.allowPolling, forKey: .allowPolling)
    try container.encode(self.allowWebsocket, forKey: .allowWebsocket)
  }
}

