/// Which kind of server a direct connection talks to.
///
/// OpenRouter, Azure and LM Studio are OpenAI-compatible servers, not kinds
/// of their own: the core tells OpenRouter apart by its address, and Azure
/// by its `api-version` and key header.
public enum DirectKind: Codable, Hashable, Sendable {
  case openai
  case ollama
  /// A value this build does not know, from a newer core, kept as it came.
  case unknown(String)

  public init(rawValue: String) {
    switch rawValue {
    case "openai": self = .openai
    case "ollama": self = .ollama
    default: self = .unknown(rawValue)
    }
  }

  /// The value as it goes on the wire.
  public var rawValue: String {
    switch self {
    case .openai: return "openai"
    case .ollama: return "ollama"
    case .unknown(let raw): return raw
    }
  }

  public init(from decoder: Decoder) throws {
    self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.singleValueContainer()
    try container.encode(rawValue)
  }
}

/// For [DirectKind.openai]: the chat completions API, or the newer
/// responses API.
public enum DirectApiMode: Codable, Hashable, Sendable {
  case chat
  case responses
  /// A value this build does not know, from a newer core, kept as it came.
  case unknown(String)

  public init(rawValue: String) {
    switch rawValue {
    case "chat": self = .chat
    case "responses": self = .responses
    default: self = .unknown(rawValue)
    }
  }

  /// The value as it goes on the wire.
  public var rawValue: String {
    switch self {
    case .chat: return "chat"
    case .responses: return "responses"
    case .unknown(let raw): return raw
    }
  }

  public init(from decoder: Decoder) throws {
    self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.singleValueContainer()
    try container.encode(rawValue)
  }
}

/// A direct connection, as the settings list shows it.
///
/// Never its secrets. An API key or a header value is written once and
/// then only reported as present -- the same rule `servers.*` follows,
/// because a key read back is a key a compromised window could copy out.
public struct DirectConnectionSummary: Codable, Equatable, Sendable {
  public var id: String
  public var name: String
  public var kind: DirectKind
  public var baseUrl: String
  public var apiMode: DirectApiMode
  /// Azure's `api-version`, when set.
  public var apiVersion: String?
  /// Send the key in an `api-key` header (Azure) rather than as a bearer
  /// token.
  public var apiKeyHeader: Bool
  public var modelIdPrefix: String?
  public var enabled: Bool
  public var hasApiKey: Bool
  /// Names only; values are secrets like the key.
  public var customHeaderNames: [String]
  /// For servers without model discovery.
  public var manualModelIds: [String]
  public var allowSelfSignedCertificates: Bool
  public var openRouter: Bool
  public var ollamaCloud: Bool
  /// Kept in the Open WebUI account's settings rather than on this
  /// computer. Its chats go through Open WebUI, which asks the app
  /// to make the request -- Open WebUI's own "direct connections".
  public var openWebUi: Bool
  /// False for an Open WebUI connection this app cannot use (an
  /// authentication kind it does not support). Listed, not editable.
  public var compatible: Bool
  /// Labels applied to this connection's models in the picker.
  public var tags: [String]
  /// The client certificate and key for mutual TLS, by file name only:
  /// the PEM itself, like a key, never comes back out.
  public var certificateLabel: String?
  public var privateKeyLabel: String?

  public init(
    id: String,
    name: String,
    kind: DirectKind,
    baseUrl: String,
    apiMode: DirectApiMode = .chat,
    apiVersion: String? = nil,
    apiKeyHeader: Bool = false,
    modelIdPrefix: String? = nil,
    enabled: Bool = true,
    hasApiKey: Bool = false,
    customHeaderNames: [String] = [],
    manualModelIds: [String] = [],
    allowSelfSignedCertificates: Bool = false,
    openRouter: Bool = false,
    ollamaCloud: Bool = false,
    openWebUi: Bool = false,
    compatible: Bool = true,
    tags: [String] = [],
    certificateLabel: String? = nil,
    privateKeyLabel: String? = nil
  ) {
    self.id = id
    self.name = name
    self.kind = kind
    self.baseUrl = baseUrl
    self.apiMode = apiMode
    self.apiVersion = apiVersion
    self.apiKeyHeader = apiKeyHeader
    self.modelIdPrefix = modelIdPrefix
    self.enabled = enabled
    self.hasApiKey = hasApiKey
    self.customHeaderNames = customHeaderNames
    self.manualModelIds = manualModelIds
    self.allowSelfSignedCertificates = allowSelfSignedCertificates
    self.openRouter = openRouter
    self.ollamaCloud = ollamaCloud
    self.openWebUi = openWebUi
    self.compatible = compatible
    self.tags = tags
    self.certificateLabel = certificateLabel
    self.privateKeyLabel = privateKeyLabel
  }

  private enum CodingKeys: String, CodingKey {
    case id
    case name
    case kind
    case baseUrl
    case apiMode
    case apiVersion
    case apiKeyHeader
    case modelIdPrefix
    case enabled
    case hasApiKey
    case customHeaderNames
    case manualModelIds
    case allowSelfSignedCertificates
    case openRouter
    case ollamaCloud
    case openWebUi
    case compatible
    case tags
    case certificateLabel
    case privateKeyLabel
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)
    self.id = try container.decode(String.self, forKey: .id)
    self.name = try container.decode(String.self, forKey: .name)
    self.kind = try container.decode(DirectKind.self, forKey: .kind)
    self.baseUrl = try container.decode(String.self, forKey: .baseUrl)
    self.apiMode = try container.decodeIfPresent(DirectApiMode.self, forKey: .apiMode) ?? .chat
    self.apiVersion = try container.decodeIfPresent(String.self, forKey: .apiVersion)
    self.apiKeyHeader = try container.decodeIfPresent(Bool.self, forKey: .apiKeyHeader) ?? false
    self.modelIdPrefix = try container.decodeIfPresent(String.self, forKey: .modelIdPrefix)
    self.enabled = try container.decodeIfPresent(Bool.self, forKey: .enabled) ?? true
    self.hasApiKey = try container.decodeIfPresent(Bool.self, forKey: .hasApiKey) ?? false
    self.customHeaderNames = try container.decodeIfPresent([String].self, forKey: .customHeaderNames) ?? []
    self.manualModelIds = try container.decodeIfPresent([String].self, forKey: .manualModelIds) ?? []
    self.allowSelfSignedCertificates = try container.decodeIfPresent(Bool.self, forKey: .allowSelfSignedCertificates) ?? false
    self.openRouter = try container.decodeIfPresent(Bool.self, forKey: .openRouter) ?? false
    self.ollamaCloud = try container.decodeIfPresent(Bool.self, forKey: .ollamaCloud) ?? false
    self.openWebUi = try container.decodeIfPresent(Bool.self, forKey: .openWebUi) ?? false
    self.compatible = try container.decodeIfPresent(Bool.self, forKey: .compatible) ?? true
    self.tags = try container.decodeIfPresent([String].self, forKey: .tags) ?? []
    self.certificateLabel = try container.decodeIfPresent(String.self, forKey: .certificateLabel)
    self.privateKeyLabel = try container.decodeIfPresent(String.self, forKey: .privateKeyLabel)
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: CodingKeys.self)
    try container.encode(self.id, forKey: .id)
    try container.encode(self.name, forKey: .name)
    try container.encode(self.kind, forKey: .kind)
    try container.encode(self.baseUrl, forKey: .baseUrl)
    try container.encode(self.apiMode, forKey: .apiMode)
    try container.encodeIfPresent(self.apiVersion, forKey: .apiVersion)
    try container.encode(self.apiKeyHeader, forKey: .apiKeyHeader)
    try container.encodeIfPresent(self.modelIdPrefix, forKey: .modelIdPrefix)
    try container.encode(self.enabled, forKey: .enabled)
    try container.encode(self.hasApiKey, forKey: .hasApiKey)
    try container.encode(self.customHeaderNames, forKey: .customHeaderNames)
    try container.encode(self.manualModelIds, forKey: .manualModelIds)
    try container.encode(self.allowSelfSignedCertificates, forKey: .allowSelfSignedCertificates)
    try container.encode(self.openRouter, forKey: .openRouter)
    try container.encode(self.ollamaCloud, forKey: .ollamaCloud)
    try container.encode(self.openWebUi, forKey: .openWebUi)
    try container.encode(self.compatible, forKey: .compatible)
    try container.encode(self.tags, forKey: .tags)
    try container.encodeIfPresent(self.certificateLabel, forKey: .certificateLabel)
    try container.encodeIfPresent(self.privateKeyLabel, forKey: .privateKeyLabel)
  }
}

/// Reply to `direct.list` and to every change.
public struct DirectConnectionList: Codable, Equatable, Sendable {
  public var connections: [DirectConnectionSummary]
  /// Keep direct chats on this computer only, rather than mirroring them
  /// to the Open WebUI server.
  public var localHistory: Bool
  /// The signed-in server lets its users keep direct connections in their
  /// account, so the settings offer a section for them.
  public var openWebUiAvailable: Bool
  /// The signed-in server moved its users' direct connections to Tether
  /// (Open WebUI 0.13.4 and later), so the settings say so where they were.
  public var openWebUiMovedToTether: Bool
  /// The app was set up to use direct connections rather than an Open
  /// WebUI server (the welcome screen's choice).
  public var preferred: Bool
  /// At least one connection on this computer is on and complete, so the
  /// app can be used with no server at all.
  public var usable: Bool
  /// The connections kept in the Open WebUI account could not be read
  /// this time (`direct.reload` tries again). The ones listed, if any,
  /// are the last that were.
  public var openWebUiLoadFailed: Bool

  public init(
    connections: [DirectConnectionSummary] = [],
    localHistory: Bool = false,
    openWebUiAvailable: Bool = false,
    openWebUiMovedToTether: Bool = false,
    preferred: Bool = false,
    usable: Bool = false,
    openWebUiLoadFailed: Bool = false
  ) {
    self.connections = connections
    self.localHistory = localHistory
    self.openWebUiAvailable = openWebUiAvailable
    self.openWebUiMovedToTether = openWebUiMovedToTether
    self.preferred = preferred
    self.usable = usable
    self.openWebUiLoadFailed = openWebUiLoadFailed
  }

  private enum CodingKeys: String, CodingKey {
    case connections
    case localHistory
    case openWebUiAvailable
    case openWebUiMovedToTether
    case preferred
    case usable
    case openWebUiLoadFailed
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)
    self.connections = try container.decodeIfPresent([DirectConnectionSummary].self, forKey: .connections) ?? []
    self.localHistory = try container.decodeIfPresent(Bool.self, forKey: .localHistory) ?? false
    self.openWebUiAvailable = try container.decodeIfPresent(Bool.self, forKey: .openWebUiAvailable) ?? false
    self.openWebUiMovedToTether = try container.decodeIfPresent(Bool.self, forKey: .openWebUiMovedToTether) ?? false
    self.preferred = try container.decodeIfPresent(Bool.self, forKey: .preferred) ?? false
    self.usable = try container.decodeIfPresent(Bool.self, forKey: .usable) ?? false
    self.openWebUiLoadFailed = try container.decodeIfPresent(Bool.self, forKey: .openWebUiLoadFailed) ?? false
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: CodingKeys.self)
    try container.encode(self.connections, forKey: .connections)
    try container.encode(self.localHistory, forKey: .localHistory)
    try container.encode(self.openWebUiAvailable, forKey: .openWebUiAvailable)
    try container.encode(self.openWebUiMovedToTether, forKey: .openWebUiMovedToTether)
    try container.encode(self.preferred, forKey: .preferred)
    try container.encode(self.usable, forKey: .usable)
    try container.encode(self.openWebUiLoadFailed, forKey: .openWebUiLoadFailed)
  }
}

/// Params for `direct.save` and `direct.test`.
///
/// [apiKey] and [customHeaders] follow the servers rule: null keeps what is
/// stored, an empty value clears it. Changing where the connection points
/// drops its stored secrets unless new ones are given in the same edit --
/// the core's own rule, so a key cannot silently follow a URL somewhere
/// else.
public struct DirectConnectionEdit: Codable, Equatable, Sendable {
  /// Null adds a connection.
  public var id: String?
  public var name: String
  public var kind: DirectKind
  public var baseUrl: String
  public var apiMode: DirectApiMode
  public var apiVersion: String?
  public var apiKeyHeader: Bool
  public var modelIdPrefix: String?
  public var enabled: Bool
  /// For a new connection: keep it in the Open WebUI account instead of
  /// on this computer. An existing one stays where it is.
  public var openWebUi: Bool
  public var apiKey: String?
  public var customHeaders: [String: String]?
  public var manualModelIds: [String]
  public var allowSelfSignedCertificates: Bool
  public var tags: [String]
  /// Mutual TLS: a PEM client certificate chain and its private key, with
  /// the file names they were picked from. Secrets, so the `apiKey` rule:
  /// null keeps what is stored, empty clears it.
  public var certificatePem: String?
  public var certificateLabel: String?
  public var privateKeyPem: String?
  public var privateKeyLabel: String?
  public var privateKeyPassword: String?

  public init(
    id: String? = nil,
    name: String,
    kind: DirectKind,
    baseUrl: String,
    apiMode: DirectApiMode = .chat,
