/// Which window opened this RPC connection.
///
/// Several renderer windows share one daemon, and the daemon broadcasts
/// events to all of them. The kind lets it skip work nobody is looking at —
/// the quick-ask window never needs the sidebar's chat pages.
public enum WindowKind: Codable, Hashable, Sendable {
  /// The full app shell: sidebar, transcript, right pane.
  case main
  /// Frameless always-on-top global-hotkey window.
  case quickAsk
  /// A headless connection used by tests and `conduitd --probe`.
  case headless
  /// A value this build does not know, from a newer core, kept as it came.
  case unknown(String)

  public init(rawValue: String) {
    switch rawValue {
    case "main": self = .main
    case "quickAsk": self = .quickAsk
    case "headless": self = .headless
    default: self = .unknown(rawValue)
    }
  }

  /// The value as it goes on the wire.
  public var rawValue: String {
    switch self {
    case .main: return "main"
    case .quickAsk: return "quickAsk"
    case .headless: return "headless"
    case .unknown(let raw): return raw
    }
  }

  public init(from decoder: Decoder) throws {
    self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.singleValueContainer()
    try container.encode(rawValue)
  }
}

/// First frame the UI sends after the socket opens.
///
/// Sent as a normal JSON-RPC request (`system.handshake`) rather than as
/// WebSocket subprotocol data: the token check already happened at upgrade
/// time, so this carries only what the daemon needs to shape the session.
public struct HandshakeRequest: Codable, Equatable, Sendable {
  /// Must equal the daemon's [kConduitProtocolVersion] exactly.
  public var protocolVersion: String
  public var clientName: String
  public var clientVersion: String
  public var windowKind: WindowKind
  /// BCP-47 tag, e.g. `zh-Hant`. The daemon does not localize anything; it
  /// forwards this to the server for `Accept-Language` and stores it so
  /// background notifications can be localized by the UI on click.
  public var locale: String

  public init(
    protocolVersion: String,
    clientName: String,
    clientVersion: String,
    windowKind: WindowKind,
    locale: String
  ) {
    self.protocolVersion = protocolVersion
    self.clientName = clientName
    self.clientVersion = clientVersion
    self.windowKind = windowKind
    self.locale = locale
  }

  private enum CodingKeys: String, CodingKey {
    case protocolVersion
    case clientName
    case clientVersion
    case windowKind
    case locale
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)
    self.protocolVersion = try container.decode(String.self, forKey: .protocolVersion)
    self.clientName = try container.decode(String.self, forKey: .clientName)
    self.clientVersion = try container.decode(String.self, forKey: .clientVersion)
    self.windowKind = try container.decode(WindowKind.self, forKey: .windowKind)
    self.locale = try container.decode(String.self, forKey: .locale)
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: CodingKeys.self)
    try container.encode(self.protocolVersion, forKey: .protocolVersion)
    try container.encode(self.clientName, forKey: .clientName)
    try container.encode(self.clientVersion, forKey: .clientVersion)
    try container.encode(self.windowKind, forKey: .windowKind)
    try container.encode(self.locale, forKey: .locale)
  }
}

