    let container = try decoder.container(keyedBy: CodingKeys.self)
    self.protocolVersion = try container.decode(String.self, forKey: .protocolVersion)
    self.daemonVersion = try container.decode(String.self, forKey: .daemonVersion)
    self.sessionId = try container.decode(String.self, forKey: .sessionId)
    self.capabilities = try container.decode(Capabilities.self, forKey: .capabilities)
    self.paths = try container.decode(DaemonPaths.self, forKey: .paths)
    self.platform = try container.decode(String.self, forKey: .platform)
    self.needsOnboarding = try container.decodeIfPresent(Bool.self, forKey: .needsOnboarding) ?? false
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: CodingKeys.self)
    try container.encode(self.protocolVersion, forKey: .protocolVersion)
    try container.encode(self.daemonVersion, forKey: .daemonVersion)
    try container.encode(self.sessionId, forKey: .sessionId)
    try container.encode(self.capabilities, forKey: .capabilities)
    try container.encode(self.paths, forKey: .paths)
    try container.encode(self.platform, forKey: .platform)
    try container.encode(self.needsOnboarding, forKey: .needsOnboarding)
  }
