/// The cadences core reads in a Hermes job's cron schedule (the core's
/// `HermesCadenceKind`).
public enum HermesCadenceKind: Codable, Hashable, Sendable {
  case none
  case everyMinute
  case everyMinutes
  case everyHour
  case everyHours
  case daily
  case weekdays
  case weekends
  case weekly
  case monthly
  /// A value this build does not know, from a newer core, kept as it came.
  case unknown(String)

  public init(rawValue: String) {
    switch rawValue {
    case "none": self = .none
    case "everyMinute": self = .everyMinute
    case "everyMinutes": self = .everyMinutes
    case "everyHour": self = .everyHour
    case "everyHours": self = .everyHours
    case "daily": self = .daily
    case "weekdays": self = .weekdays
    case "weekends": self = .weekends
    case "weekly": self = .weekly
    case "monthly": self = .monthly
    default: self = .unknown(rawValue)
    }
  }

  /// The value as it goes on the wire.
  public var rawValue: String {
    switch self {
    case .none: return "none"
    case .everyMinute: return "everyMinute"
    case .everyMinutes: return "everyMinutes"
    case .everyHour: return "everyHour"
    case .everyHours: return "everyHours"
    case .daily: return "daily"
    case .weekdays: return "weekdays"
    case .weekends: return "weekends"
    case .weekly: return "weekly"
    case .monthly: return "monthly"
    case .unknown(let raw): return raw
    }
  }

  public init(from decoder: Decoder) throws {
    self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.singleValueContainer()
    try container.encode(rawValue)
  }
}

