/// An open room, as its pane shows it. Reply to `hermes.rooms.watch`, and
/// payload of `hermes.rooms.changed` (scoped to `hermes-room:<roomId>`)
/// while a window watches it: the daemon reads the room every 2 s.
public struct HermesRoomView: Codable, Equatable, Sendable {
  public var roomId: String
  /// Read once.
  public var loaded: Bool
  /// None until read, or when the read failed with nothing read before.
  public var room: HermesRoomDto?
  public var context: HermesRoomContextDto?
  /// The room left the gateway (disbanded, or not this user's).
  public var gone: Bool
  /// The last read failed (the last good read stays shown).
  public var readFailed: Bool
  /// Its driver runs: messages can be sent.
  public var running: Bool
  /// Its bots are at work: Stop applies.
  public var working: Bool
  public var sending: Bool
  /// Words Hermes may or may not have; sending them again posts them at
  /// most once.
  public var unsentText: String?
  /// Who-answers modes Hermes offers (none: Hermes cannot choose).
  public var routingModes: [HermesRoomRouting]
  public var items: [HermesRoomItemDto]
  public var members: [HermesRoomMemberStatusDto]
  public var actions: [HermesRoomActionDto]
  /// The Hermes connection this view was read on (`HermesChanged.connection`).
  public var connection: String?

  public init(
    roomId: String,
    loaded: Bool = false,
    room: HermesRoomDto? = nil,
    context: HermesRoomContextDto? = nil,
    gone: Bool = false,
    readFailed: Bool = false,
    running: Bool = false,
    working: Bool = false,
    sending: Bool = false,
    unsentText: String? = nil,
    routingModes: [HermesRoomRouting] = [],
    items: [HermesRoomItemDto] = [],
    members: [HermesRoomMemberStatusDto] = [],
    actions: [HermesRoomActionDto] = [],
    connection: String? = nil
  ) {
    self.roomId = roomId
    self.loaded = loaded
    self.room = room
    self.context = context
    self.gone = gone
    self.readFailed = readFailed
    self.running = running
    self.working = working
    self.sending = sending
    self.unsentText = unsentText
    self.routingModes = routingModes
    self.items = items
    self.members = members
    self.actions = actions
    self.connection = connection
  }

  private enum CodingKeys: String, CodingKey {
    case roomId
    case loaded
    case room
    case context
    case gone
    case readFailed
    case running
    case working
    case sending
    case unsentText
    case routingModes
    case items
    case members
    case actions
    case connection
  }

