    let container = try decoder.container(keyedBy: CodingKeys.self)
    self.roomId = try container.decode(String.self, forKey: .roomId)
    self.loaded = try container.decodeIfPresent(Bool.self, forKey: .loaded) ?? false
    self.room = try container.decodeIfPresent(HermesRoomDto.self, forKey: .room)
    self.context = try container.decodeIfPresent(HermesRoomContextDto.self, forKey: .context)
    self.gone = try container.decodeIfPresent(Bool.self, forKey: .gone) ?? false
    self.readFailed = try container.decodeIfPresent(Bool.self, forKey: .readFailed) ?? false
    self.running = try container.decodeIfPresent(Bool.self, forKey: .running) ?? false
    self.working = try container.decodeIfPresent(Bool.self, forKey: .working) ?? false
    self.sending = try container.decodeIfPresent(Bool.self, forKey: .sending) ?? false
    self.unsentText = try container.decodeIfPresent(String.self, forKey: .unsentText)
    self.routingModes = try container.decodeIfPresent([HermesRoomRouting].self, forKey: .routingModes) ?? []
    self.items = try container.decodeIfPresent([HermesRoomItemDto].self, forKey: .items) ?? []
    self.members = try container.decodeIfPresent([HermesRoomMemberStatusDto].self, forKey: .members) ?? []
    self.actions = try container.decodeIfPresent([HermesRoomActionDto].self, forKey: .actions) ?? []
    self.connection = try container.decodeIfPresent(String.self, forKey: .connection)
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: CodingKeys.self)
    try container.encode(self.roomId, forKey: .roomId)
    try container.encode(self.loaded, forKey: .loaded)
    try container.encodeIfPresent(self.room, forKey: .room)
    try container.encodeIfPresent(self.context, forKey: .context)
    try container.encode(self.gone, forKey: .gone)
    try container.encode(self.readFailed, forKey: .readFailed)
    try container.encode(self.running, forKey: .running)
    try container.encode(self.working, forKey: .working)
    try container.encode(self.sending, forKey: .sending)
    try container.encodeIfPresent(self.unsentText, forKey: .unsentText)
    try container.encode(self.routingModes, forKey: .routingModes)
    try container.encode(self.items, forKey: .items)
    try container.encode(self.members, forKey: .members)
    try container.encode(self.actions, forKey: .actions)
    try container.encodeIfPresent(self.connection, forKey: .connection)
  }
