/// How a sign-in step went.
public enum LibreChatSignInOutcome: Codable, Hashable, Sendable {
  /// Signed in, saved, and in charge of the chats.
  case signedIn
  /// The account uses two-step verification: `librechat.verify` with
  /// [LibreChatSignInResult.flowId] and a code.
  case twoFactorRequired
  /// The server refused the email or password (its words in
  /// [LibreChatSignInResult.serverMessage]).
  case rejected
  /// The code was not accepted; try another.
  case invalidCode
  /// The two-step sign-in ran out of time or was never started: start over.
  case expired
  /// The server could not be reached.
  case unreachable
  /// Signed in and saved, but an answer is still being written in the
  /// account it would replace: ask, then `accounts.switch` with `force`.
  case blockedByActiveReply
  /// The single sign-on left no session.
  case ssoUnfinished
  /// Something else failed, such as saving the session.
  case failed
  /// A value this build does not know, from a newer core, kept as it came.
  case unknown(String)

  public init(rawValue: String) {
    switch rawValue {
    case "signedIn": self = .signedIn
    case "twoFactorRequired": self = .twoFactorRequired
    case "rejected": self = .rejected
    case "invalidCode": self = .invalidCode
    case "expired": self = .expired
    case "unreachable": self = .unreachable
    case "blockedByActiveReply": self = .blockedByActiveReply
    case "ssoUnfinished": self = .ssoUnfinished
    case "failed": self = .failed
    default: self = .unknown(rawValue)
    }
  }

  /// The value as it goes on the wire.
  public var rawValue: String {
    switch self {
    case .signedIn: return "signedIn"
    case .twoFactorRequired: return "twoFactorRequired"
    case .rejected: return "rejected"
    case .invalidCode: return "invalidCode"
    case .expired: return "expired"
    case .unreachable: return "unreachable"
    case .blockedByActiveReply: return "blockedByActiveReply"
    case .ssoUnfinished: return "ssoUnfinished"
    case .failed: return "failed"
    case .unknown(let raw): return raw
    }
  }

  public init(from decoder: Decoder) throws {
    self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.singleValueContainer()
    try container.encode(rawValue)
  }
}

