/// Where a note falls in the notes list's time groups, by when it last
/// changed: the core's own calendar days, as the phone groups them.
public enum NoteSection: Codable, Hashable, Sendable {
  case today
  case yesterday
  case previous7Days
  case previous30Days
  case older
  /// A value this build does not know, from a newer core, kept as it came.
  case unknown(String)

  public init(rawValue: String) {
    switch rawValue {
    case "today": self = .today
    case "yesterday": self = .yesterday
    case "previous7Days": self = .previous7Days
    case "previous30Days": self = .previous30Days
    case "older": self = .older
    default: self = .unknown(rawValue)
    }
  }

  /// The value as it goes on the wire.
  public var rawValue: String {
    switch self {
    case .today: return "today"
    case .yesterday: return "yesterday"
    case .previous7Days: return "previous7Days"
    case .previous30Days: return "previous30Days"
    case .older: return "older"
    case .unknown(let raw): return raw
    }
  }

  public init(from decoder: Decoder) throws {
    self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.singleValueContainer()
    try container.encode(rawValue)
  }
}

