/// What a notification is about.
public enum NotifyKind: Codable, Hashable, Sendable {
  /// An answer finished (or failed).
  case answer
  /// Someone else posted in a channel or a direct message.
  case channelMessage
  /// A value this build does not know, from a newer core, kept as it came.
  case unknown(String)

  public init(rawValue: String) {
    switch rawValue {
    case "answer": self = .answer
    case "channelMessage": self = .channelMessage
    default: self = .unknown(rawValue)
    }
  }

  /// The value as it goes on the wire.
  public var rawValue: String {
    switch self {
    case .answer: return "answer"
    case .channelMessage: return "channelMessage"
    case .unknown(let raw): return raw
    }
  }

  public init(from decoder: Decoder) throws {
    self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.singleValueContainer()
    try container.encode(rawValue)
  }
}

/// Where a notification goes.
public enum NotifySurface: Codable, Hashable, Sendable {
  case banner
  case system
  case silent
  case suppressed
