/// Where a queue is in handing its drafts over (the core's
/// `ChatDraftQueuePhase`).
public enum QueuePhase: Codable, Hashable, Sendable {
  case idle
  case stopping
  case admitting
  /// A value this build does not know, from a newer core, kept as it came.
  case unknown(String)

  public init(rawValue: String) {
    switch rawValue {
    case "idle": self = .idle
    case "stopping": self = .stopping
    case "admitting": self = .admitting
    default: self = .unknown(rawValue)
    }
  }

  /// The value as it goes on the wire.
  public var rawValue: String {
    switch self {
    case .idle: return "idle"
    case .stopping: return "stopping"
    case .admitting: return "admitting"
    case .unknown(let raw): return raw
    }
  }

  public init(from decoder: Decoder) throws {
    self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.singleValueContainer()
    try container.encode(rawValue)
  }
}

/// A chat's queue: the core's `ChatDraftQueue`. Reply to every `queue.*`
/// method and the payload of `queue.changed`.
///
/// Every draft waiting when the answer finishes goes out as one message
/// (the texts joined by a blank line, the files in order), as Open WebUI's
/// own queue does. Queued drafts live in the daemon's memory only.
public struct QueueState: Codable, Equatable, Sendable {
  public var chatId: String
  public var drafts: [QueuedDraftDto]
  public var phase: QueuePhase
  /// The last batch was refused before it was sent; nothing goes out
  /// again until `queue.retry` (or an edit).
  public var admissionFailed: Bool
  /// A message typed now would be queued rather than sent: an answer is
  /// running in an Open WebUI chat that takes queued turns.
  public var offer: Bool

  public init(
    chatId: String,
    drafts: [QueuedDraftDto] = [],
    phase: QueuePhase = .idle,
    admissionFailed: Bool = false,
    offer: Bool = false
  ) {
    self.chatId = chatId
    self.drafts = drafts
    self.phase = phase
    self.admissionFailed = admissionFailed
    self.offer = offer
  }

  private enum CodingKeys: String, CodingKey {
    case chatId
    case drafts
    case phase
    case admissionFailed
    case offer
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)
    self.chatId = try container.decode(String.self, forKey: .chatId)
    self.drafts = try container.decodeIfPresent([QueuedDraftDto].self, forKey: .drafts) ?? []
    self.phase = try container.decodeIfPresent(QueuePhase.self, forKey: .phase) ?? .idle
    self.admissionFailed = try container.decodeIfPresent(Bool.self, forKey: .admissionFailed) ?? false
    self.offer = try container.decodeIfPresent(Bool.self, forKey: .offer) ?? false
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: CodingKeys.self)
    try container.encode(self.chatId, forKey: .chatId)
    try container.encode(self.drafts, forKey: .drafts)
    try container.encode(self.phase, forKey: .phase)
    try container.encode(self.admissionFailed, forKey: .admissionFailed)
    try container.encode(self.offer, forKey: .offer)
  }
}

