/// A configured server, as the renderer is allowed to see it.
///
/// Deliberately *not* the core's `ServerConfig`, which also holds an API key,
/// a PEM private key and its passphrase. Those never cross this boundary:
/// the daemon attaches credentials to outbound requests itself, which is the
/// same reason `/files/{serverId}/{fileId}` is proxied rather than handed to
/// the renderer as a signed URL. What the UI needs is whether a credential
/// exists, so it can render "configured" next to a field and offer to
/// replace it -- never the value.
public struct ServerSummary: Codable, Equatable, Sendable {
  public var id: String
  public var name: String
  public var url: String
  /// Exactly one server is active at a time; it is the one every other
  /// namespace implicitly addresses.
  public var isActive: Bool
  /// UTC milliseconds, or null if this server has never connected.
  public var lastConnectedMs: Int?
  public var allowSelfSignedCertificates: Bool
  /// Whether a client certificate *and* key are both present. The UI shows
  /// this as a state, and the labels below as the filenames the user
  /// picked; neither reveals key material.
  public var hasMutualTlsCredentials: Bool
  public var mtlsCertificateLabel: String?
  public var mtlsPrivateKeyLabel: String?
  /// Custom header *names* only. A header value is frequently a bearer
  /// token for a reverse proxy, so the values stay daemon-side; the setup
  /// form edits them by sending replacements, not by reading them back.
  public var customHeaderNames: [String]
  /// Whether switching to this server would restore a session rather than
  /// ask for credentials. True for the active server when it is signed in,
  /// and for any server holding a vaulted token.
  ///
  /// A hint for the UI's "signed in" marker, not a guarantee: the server
  /// may have revoked the token since, which is only discovered by using
  /// it.
  public var hasStoredSession: Bool

  public init(
    id: String,
    name: String,
    url: String,
    isActive: Bool = false,
    lastConnectedMs: Int? = nil,
    allowSelfSignedCertificates: Bool = false,
    hasMutualTlsCredentials: Bool = false,
    mtlsCertificateLabel: String? = nil,
    mtlsPrivateKeyLabel: String? = nil,
    customHeaderNames: [String] = [],
    hasStoredSession: Bool = false
  ) {
    self.id = id
    self.name = name
    self.url = url
    self.isActive = isActive
    self.lastConnectedMs = lastConnectedMs
    self.allowSelfSignedCertificates = allowSelfSignedCertificates
    self.hasMutualTlsCredentials = hasMutualTlsCredentials
    self.mtlsCertificateLabel = mtlsCertificateLabel
    self.mtlsPrivateKeyLabel = mtlsPrivateKeyLabel
    self.customHeaderNames = customHeaderNames
    self.hasStoredSession = hasStoredSession
  }

  private enum CodingKeys: String, CodingKey {
    case id
    case name
    case url
    case isActive
    case lastConnectedMs
    case allowSelfSignedCertificates
    case hasMutualTlsCredentials
    case mtlsCertificateLabel
    case mtlsPrivateKeyLabel
    case customHeaderNames
    case hasStoredSession
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)
    self.id = try container.decode(String.self, forKey: .id)
    self.name = try container.decode(String.self, forKey: .name)
    self.url = try container.decode(String.self, forKey: .url)
    self.isActive = try container.decodeIfPresent(Bool.self, forKey: .isActive) ?? false
    self.lastConnectedMs = try container.decodeIfPresent(Int.self, forKey: .lastConnectedMs)
    self.allowSelfSignedCertificates = try container.decodeIfPresent(Bool.self, forKey: .allowSelfSignedCertificates) ?? false
    self.hasMutualTlsCredentials = try container.decodeIfPresent(Bool.self, forKey: .hasMutualTlsCredentials) ?? false
    self.mtlsCertificateLabel = try container.decodeIfPresent(String.self, forKey: .mtlsCertificateLabel)
    self.mtlsPrivateKeyLabel = try container.decodeIfPresent(String.self, forKey: .mtlsPrivateKeyLabel)
    self.customHeaderNames = try container.decodeIfPresent([String].self, forKey: .customHeaderNames) ?? []
    self.hasStoredSession = try container.decodeIfPresent(Bool.self, forKey: .hasStoredSession) ?? false
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: CodingKeys.self)
    try container.encode(self.id, forKey: .id)
    try container.encode(self.name, forKey: .name)
    try container.encode(self.url, forKey: .url)
    try container.encode(self.isActive, forKey: .isActive)
    try container.encodeIfPresent(self.lastConnectedMs, forKey: .lastConnectedMs)
    try container.encode(self.allowSelfSignedCertificates, forKey: .allowSelfSignedCertificates)
    try container.encode(self.hasMutualTlsCredentials, forKey: .hasMutualTlsCredentials)
    try container.encodeIfPresent(self.mtlsCertificateLabel, forKey: .mtlsCertificateLabel)
    try container.encodeIfPresent(self.mtlsPrivateKeyLabel, forKey: .mtlsPrivateKeyLabel)
    try container.encode(self.customHeaderNames, forKey: .customHeaderNames)
    try container.encode(self.hasStoredSession, forKey: .hasStoredSession)
  }
}

/// Params for `servers.update`, and the server half of `accounts.add`.
///
/// Every secret field is nullable and "null means leave alone", so the setup
/// form can save a rename without having to round-trip a private key it was
/// never given. [clearMutualTls] is how a caller actually removes one, since
/// null cannot mean both "unchanged" and "delete".
///
/// There is deliberately no API key here. The core strips `apiKey` from every
/// persisted `ServerConfig` -- an API key is a credential, kept in secure
/// storage, not server metadata -- so a field for it would be one the daemon
/// silently discards. `auth.loginWithApiKey` is the way in.
public struct ServerDraft: Codable, Equatable, Sendable {
  /// The account whose server this edits, on `servers.update`. Ignored by
  /// `accounts.add`, which always makes a new account.
  public var id: String?
  public var name: String
  public var url: String
  public var allowSelfSignedCertificates: Bool
  public var mtlsCertificateChainPem: String?
  public var mtlsCertificateLabel: String?
  public var mtlsPrivateKeyPem: String?
  public var mtlsPrivateKeyLabel: String?
  public var mtlsPrivateKeyPassword: String?
  public var clearMutualTls: Bool
  /// Replaces the whole header map when present, leaves it alone when null.
  public var customHeaders: [String: String]?

  public init(
    id: String? = nil,
    name: String,
    url: String,
    allowSelfSignedCertificates: Bool = false,
    mtlsCertificateChainPem: String? = nil,
    mtlsCertificateLabel: String? = nil,
    mtlsPrivateKeyPem: String? = nil,
    mtlsPrivateKeyLabel: String? = nil,
    mtlsPrivateKeyPassword: String? = nil,
    clearMutualTls: Bool = false,
    customHeaders: [String: String]? = nil
  ) {
    self.id = id
    self.name = name
    self.url = url
    self.allowSelfSignedCertificates = allowSelfSignedCertificates
    self.mtlsCertificateChainPem = mtlsCertificateChainPem
    self.mtlsCertificateLabel = mtlsCertificateLabel
    self.mtlsPrivateKeyPem = mtlsPrivateKeyPem
    self.mtlsPrivateKeyLabel = mtlsPrivateKeyLabel
    self.mtlsPrivateKeyPassword = mtlsPrivateKeyPassword
    self.clearMutualTls = clearMutualTls
    self.customHeaders = customHeaders
  }

  private enum CodingKeys: String, CodingKey {
    case id
    case name
    case url
    case allowSelfSignedCertificates
    case mtlsCertificateChainPem
    case mtlsCertificateLabel
    case mtlsPrivateKeyPem
    case mtlsPrivateKeyLabel
    case mtlsPrivateKeyPassword
    case clearMutualTls
    case customHeaders
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)
    self.id = try container.decodeIfPresent(String.self, forKey: .id)
    self.name = try container.decode(String.self, forKey: .name)
    self.url = try container.decode(String.self, forKey: .url)
    self.allowSelfSignedCertificates = try container.decodeIfPresent(Bool.self, forKey: .allowSelfSignedCertificates) ?? false
    self.mtlsCertificateChainPem = try container.decodeIfPresent(String.self, forKey: .mtlsCertificateChainPem)
    self.mtlsCertificateLabel = try container.decodeIfPresent(String.self, forKey: .mtlsCertificateLabel)
    self.mtlsPrivateKeyPem = try container.decodeIfPresent(String.self, forKey: .mtlsPrivateKeyPem)
    self.mtlsPrivateKeyLabel = try container.decodeIfPresent(String.self, forKey: .mtlsPrivateKeyLabel)
    self.mtlsPrivateKeyPassword = try container.decodeIfPresent(String.self, forKey: .mtlsPrivateKeyPassword)
    self.clearMutualTls = try container.decodeIfPresent(Bool.self, forKey: .clearMutualTls) ?? false
    self.customHeaders = try container.decodeIfPresent([String: String].self, forKey: .customHeaders)
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: CodingKeys.self)
    try container.encodeIfPresent(self.id, forKey: .id)
    try container.encode(self.name, forKey: .name)
    try container.encode(self.url, forKey: .url)
    try container.encode(self.allowSelfSignedCertificates, forKey: .allowSelfSignedCertificates)
    try container.encodeIfPresent(self.mtlsCertificateChainPem, forKey: .mtlsCertificateChainPem)
    try container.encodeIfPresent(self.mtlsCertificateLabel, forKey: .mtlsCertificateLabel)
    try container.encodeIfPresent(self.mtlsPrivateKeyPem, forKey: .mtlsPrivateKeyPem)
    try container.encodeIfPresent(self.mtlsPrivateKeyLabel, forKey: .mtlsPrivateKeyLabel)
    try container.encodeIfPresent(self.mtlsPrivateKeyPassword, forKey: .mtlsPrivateKeyPassword)
    try container.encode(self.clearMutualTls, forKey: .clearMutualTls)
    try container.encodeIfPresent(self.customHeaders, forKey: .customHeaders)
  }
}

/// How the daemon's last attempt to reach the active server went.
public enum ServerReachability: Codable, Hashable, Sendable {
  case reachable
  /// The request did not arrive: DNS, TLS, a refused connection, a proxy
  /// still challenging.
  case unreachable
  /// Something answered, but it is not an Open WebUI instance. Worth telling
  /// apart from unreachable, because the fix is a different URL rather than a
  /// different network.
  case notOpenWebUi
  /// Nothing has been attempted yet this launch.
  ///
  /// Also what a value this build does not know decodes as, kept as it came.
  case unknown(String)

  public init(rawValue: String) {
    switch rawValue {
    case "reachable": self = .reachable
    case "unreachable": self = .unreachable
    case "notOpenWebUi": self = .notOpenWebUi
    default: self = .unknown(rawValue)
    }
  }

  /// The value as it goes on the wire.
  public var rawValue: String {
    switch self {
    case .reachable: return "reachable"
    case .unreachable: return "unreachable"
    case .notOpenWebUi: return "notOpenWebUi"
    case .unknown(let raw): return raw
    }
  }

  public init(from decoder: Decoder) throws {
    self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.singleValueContainer()
    try container.encode(rawValue)
  }
}

/// The live state of the active server, as opposed to its stored config.
///
/// One call serves two screens that otherwise duplicate each other: the
/// version gate needs [version] and [isVersionSupported], the connection-issue
/// page needs [reachability] and [errorCode], and both need to know whether
/// there is an active server at all.
public struct ServerStatus: Codable, Equatable, Sendable {
  public var activeServerId: String?
  public var capabilities: Capabilities
  public var reachability: ServerReachability
  /// As the server reports it, or null when it has not been asked yet or
  /// did not say.
  public var version: String?
  /// Fails open. An unparseable or absent version is treated as supported,
  /// because blocking a user over a version string nobody can read is worse
  /// than letting them through.
  public var isVersionSupported: Bool
  /// The newest server version this build is known to work with, so the
  /// warning can name it rather than saying "too new".
  public var maxSupportedVersion: String
  /// Set when [reachability] is not `reachable`; localized in the UI.
  public var errorCode: String?

  public init(
    activeServerId: String? = nil,
    capabilities: Capabilities = Capabilities(),
    reachability: ServerReachability = .unknown("unknown"),
    version: String? = nil,
    isVersionSupported: Bool = true,
    maxSupportedVersion: String,
    errorCode: String? = nil
  ) {
    self.activeServerId = activeServerId
    self.capabilities = capabilities
    self.reachability = reachability
    self.version = version
    self.isVersionSupported = isVersionSupported
    self.maxSupportedVersion = maxSupportedVersion
    self.errorCode = errorCode
  }

  private enum CodingKeys: String, CodingKey {
    case activeServerId
    case capabilities
    case reachability
    case version
    case isVersionSupported
    case maxSupportedVersion
    case errorCode
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)
    self.activeServerId = try container.decodeIfPresent(String.self, forKey: .activeServerId)
    self.capabilities = try container.decodeIfPresent(Capabilities.self, forKey: .capabilities) ?? Capabilities()
    self.reachability = try container.decodeIfPresent(ServerReachability.self, forKey: .reachability) ?? .unknown("unknown")
    self.version = try container.decodeIfPresent(String.self, forKey: .version)
    self.isVersionSupported = try container.decodeIfPresent(Bool.self, forKey: .isVersionSupported) ?? true
    self.maxSupportedVersion = try container.decode(String.self, forKey: .maxSupportedVersion)
    self.errorCode = try container.decodeIfPresent(String.self, forKey: .errorCode)
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: CodingKeys.self)
    try container.encodeIfPresent(self.activeServerId, forKey: .activeServerId)
    try container.encode(self.capabilities, forKey: .capabilities)
    try container.encode(self.reachability, forKey: .reachability)
    try container.encodeIfPresent(self.version, forKey: .version)
    try container.encode(self.isVersionSupported, forKey: .isVersionSupported)
    try container.encode(self.maxSupportedVersion, forKey: .maxSupportedVersion)
    try container.encodeIfPresent(self.errorCode, forKey: .errorCode)
  }
}

