/// One address a saved Open WebUI server is reached at, in the order they
/// are tried. As [ServerSummary], no secret: header names, not values;
/// whether a client certificate and its key are saved, not the key.
public struct ServerAddressDto: Codable, Equatable, Sendable {
  public var id: String
  public var url: String
  /// What the user called it ("Home network"), or null.
  public var label: String?
  /// The address the active account reaches the server through now.
  public var inUse: Bool
  public var allowSelfSignedCertificates: Bool
  /// The custom headers sent to it, by name; their values stay with the
  /// daemon. The proxy cookie an account keeps here is not one of them.
  public var customHeaderNames: [String]
  public var hasMutualTlsCredentials: Bool
  public var mtlsCertificateLabel: String?
  public var mtlsPrivateKeyLabel: String?
  public var hasPrivateKeyPassword: Bool

  public init(
    id: String,
    url: String,
    label: String? = nil,
    inUse: Bool = false,
    allowSelfSignedCertificates: Bool = false,
    customHeaderNames: [String] = [],
    hasMutualTlsCredentials: Bool = false,
    mtlsCertificateLabel: String? = nil,
    mtlsPrivateKeyLabel: String? = nil,
    hasPrivateKeyPassword: Bool = false
  ) {
    self.id = id
    self.url = url
    self.label = label
    self.inUse = inUse
    self.allowSelfSignedCertificates = allowSelfSignedCertificates
    self.customHeaderNames = customHeaderNames
    self.hasMutualTlsCredentials = hasMutualTlsCredentials
    self.mtlsCertificateLabel = mtlsCertificateLabel
    self.mtlsPrivateKeyLabel = mtlsPrivateKeyLabel
    self.hasPrivateKeyPassword = hasPrivateKeyPassword
