    self.messageId = messageId
    self.ok = ok
    self.code = code
    self.queued = queued
    self.held = held
  }

  private enum CodingKeys: String, CodingKey {
    case chatId
    case messageId
    case ok
    case code
    case queued
    case held
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)
    self.chatId = try container.decode(String.self, forKey: .chatId)
    self.messageId = try container.decode(String.self, forKey: .messageId)
    self.ok = try container.decode(Bool.self, forKey: .ok)
    self.code = try container.decodeIfPresent(String.self, forKey: .code)
    self.queued = try container.decodeIfPresent(Bool.self, forKey: .queued) ?? false
    self.held = try container.decodeIfPresent(Bool.self, forKey: .held) ?? false
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: CodingKeys.self)
    try container.encode(self.chatId, forKey: .chatId)
    try container.encode(self.messageId, forKey: .messageId)
    try container.encode(self.ok, forKey: .ok)
    try container.encodeIfPresent(self.code, forKey: .code)
    try container.encode(self.queued, forKey: .queued)
    try container.encode(self.held, forKey: .held)
  }
}

