    case "auth.apiKeyNoLongerSupported": self = .apiKeyNoLongerSupported
    case "auth.tokenTooShort": self = .tokenTooShort
    case "auth.ldapNotEnabled": self = .ldapNotEnabled
    case "auth.twoStepRequired": self = .twoStepRequired
    case "auth.twoStepInvalidCode": self = .twoStepInvalidCode
    case "auth.twoStepExpired": self = .twoStepExpired
    case "auth.twoStepTooManyAttempts": self = .twoStepTooManyAttempts
    case "auth.twoStepFailed": self = .twoStepFailed
