  /// The code as it goes on the wire.
  public var rawValue: String {
    switch self {
    case .`internal`: return "rpc.internal"
    case .methodNotFound: return "rpc.methodNotFound"
    case .invalidParams: return "rpc.invalidParams"
    case .protocolViolation: return "rpc.protocolViolation"
    case .protocolVersionMismatch: return "rpc.protocolVersionMismatch"
    case .unauthorized: return "rpc.unauthorized"
    case .timeout: return "rpc.timeout"
    case .cancelled: return "rpc.cancelled"
    case .daemonUnavailable: return "rpc.daemonUnavailable"
    case .shuttingDown: return "rpc.shuttingDown"
    case .offline: return "net.offline"
    case .connectionFailed: return "net.connectionFailed"
    case .tlsUntrusted: return "net.tlsUntrusted"
    case .serverError: return "net.serverError"
    case .serverRedirect: return "net.serverRedirect"
    case .unauthenticated: return "auth.unauthenticated"
    case .invalidCredentials: return "auth.invalidCredentials"
    case .sessionExpired: return "auth.sessionExpired"
    case .signInFailed: return "auth.signInFailed"
    case .pendingApproval: return "auth.pendingApproval"
    case .apiKeyNotSupported: return "auth.apiKeyNotSupported"
    case .apiKeyNoLongerSupported: return "auth.apiKeyNoLongerSupported"
    case .tokenTooShort: return "auth.tokenTooShort"
