  case speechChanged(SpeechProgress)
  /// The daemon asks the window's speech engine to speak or play. Payload
  /// [SpeechCommand]; answered with `speech.report`.
  ///
  /// `speech.command`.
  case speechCommand(SpeechCommand)
  /// A watched Hermes chat's agent work changed: its subagents, processes,
  /// plan or the output a window reads. Payload [HermesWork], scoped to the
  /// chat.
  ///
  /// `hermes.work.changed`, scoped.
  case hermesWorkChanged(HermesWork)
  /// The voice call changed: its phase, words, meter or error. Payload
  /// [CallState].
  ///
  /// `calls.changed`.
  case callsChanged(CallState)
  /// The daemon asks the window to listen, or to open the realtime audio,
  /// for the call. Payload [CallCommand]; answered with `calls.report`.
  ///
  /// `calls.command`.
  case callsCommand(CallCommand)
  /// The calendars or the agenda changed: `calendar.agenda` again. No
  /// payload.
  ///
  /// `calendar.changed`.
  case calendarChanged
  /// The scheduled tasks changed: `automations.list` again (and the open
  /// task). No payload.
  ///
  /// `automations.changed`.
  case automationsChanged
  /// A Run Now moved on. Payload [AutomationRunProgress].
  ///
  /// `automations.runProgress`.
  case automationsRunProgress(AutomationRunProgress)
  /// A watched Group Chat changed: its log, its bots' state, what it waits
  /// on. Payload [HermesRoomView], scoped to `hermes-room:<roomId>`.
  ///
  /// `hermes.rooms.changed`, scoped.
  case hermesRoomsChanged(HermesRoomView)
  /// The Group Chats listed changed: one was made, renamed or disbanded,
  /// or one had news. Payload [HermesRooms].
  ///
  /// `hermes.rooms.listChanged`.
  case hermesRoomsListChanged(HermesRooms)
  /// The daemon asks the window's Foundation Models engine for a model's
  /// status, to start or stop a run, or answers a tool call. Payload
  /// [AppleCommand]; answered with `apple.report`.
  ///
  /// `apple.command`.
  case appleCommand(AppleCommand)
  /// The daemon asks the window's location services whether they are on, for
  /// permission, or for a position fix (`{{USER_LOCATION}}`). Payload
  /// [LocationCommand]; answered with `location.report`.
  ///
  /// `location.command`.
  case locationCommand(LocationCommand)
  /// The core gives a chat's composer words to insert at the caret.
  /// Payload [ComposerInsertText], scoped to the chat.
  ///
  /// `composer.insertText`, scoped.
  case composerInsertText(ComposerInsertText)
  /// An event this build does not know, from a newer core, kept as it came.
  case unknown(name: String, payload: JSONValue)

  /// Decodes `payload` as the event called `name`.
  ///
  /// A name this build does not know is `.unknown`; a known one whose payload
  /// does not fit its DTO throws. An event without a payload ignores whatever
  /// it carries.
  public static func decode(name: String, payload: JSONValue) throws -> ConduitEvent {
    switch name {
    case EventNames.turnStarted: return .turnStarted(try payload.decode(TurnStarted.self))
    case EventNames.turnDelta: return .turnDelta(try payload.decode(TurnDelta.self))
    case EventNames.turnBlocks: return .turnBlocks(try payload.decode(TurnBlocks.self))
    case EventNames.turnCompleted: return .turnCompleted(try payload.decode(TurnCompleted.self))
    case EventNames.turnFailed: return .turnFailed(try payload.decode(TurnFailed.self))
    case EventNames.turnFinished: return .turnFinished(try payload.decode(TurnFinished.self))
    case EventNames.chatsChanged: return .chatsChanged(try payload.decode(ChatsChanged.self))
    case EventNames.accountsChanged: return .accountsChanged(try payload.decode(AccountsChanged.self))
    case EventNames.serversChanged: return .serversChanged(try payload.decode(ServersChanged.self))
    case EventNames.notesChanged: return .notesChanged(try payload.decode(NotesChanged.self))
    case EventNames.channelsMessage: return .channelsMessage(try payload.decode(ChannelMessagesChanged.self))
    case EventNames.channelsTyping: return .channelsTyping(try payload.decode(ChannelTypingUsers.self))
    case EventNames.channelsChanged: return .channelsChanged
    case EventNames.channelsAppReply: return .channelsAppReply(try payload.decode(ChannelAppReplyEvent.self))
    case EventNames.channelsPosted: return .channelsPosted(try payload.decode(ChannelPosted.self))
    case EventNames.syncStatus: return .syncStatus(try payload.decode(SyncState.self))
    case EventNames.socketHealth: return .socketHealth
    case EventNames.notifyShow: return .notifyShow(try payload.decode(Notice.self))
    case EventNames.routeRemap: return .routeRemap(try payload.decode(RouteRemap.self))
    case EventNames.uiRequest: return .uiRequest(try payload.decode(UiRequest.self))
    case EventNames.uiSettled: return .uiSettled(try payload.decode(UiSettled.self))
    case EventNames.capabilitiesChanged: return .capabilitiesChanged
    case EventNames.modelsChanged: return .modelsChanged
    case EventNames.openUrl: return .openUrl(try payload.decode(OpenUrl.self))
    case EventNames.workspaceChanged: return .workspaceChanged(try payload.decode(WorkspaceChanged.self))
    case EventNames.hermesChanged: return .hermesChanged(try payload.decode(HermesChanged.self))
    case EventNames.authChanged: return .authChanged
    case EventNames.voiceChanged: return .voiceChanged(try payload.decode(VoiceModels.self))
    case EventNames.terminalDisplayFile: return .terminalDisplayFile(try payload.decode(TerminalDisplayFile.self))
    case EventNames.terminalChanged: return .terminalChanged(try payload.decode(TerminalChanged.self))
    case EventNames.settingsChanged: return .settingsChanged
    case EventNames.notificationsChanged: return .notificationsChanged
    case EventNames.notificationsAnswered: return .notificationsAnswered(try payload.decode(AnswerNotice.self))
    case EventNames.queueChanged: return .queueChanged(try payload.decode(QueueState.self))
    case EventNames.messagesMerge: return .messagesMerge(try payload.decode(MergeProgress.self))
    case EventNames.handoffRequested: return .handoffRequested(try payload.decode(HandoffRequest.self))
    case EventNames.handoffSettled: return .handoffSettled(try payload.decode(HandoffSettled.self))
    case EventNames.chatPromptsChanged: return .chatPromptsChanged(try payload.decode(ChatPromptState.self))
    case EventNames.mcpAppsEvent: return .mcpAppsEvent(try payload.decode(McpAppEvent.self))
    case EventNames.speechChanged: return .speechChanged(try payload.decode(SpeechProgress.self))
    case EventNames.speechCommand: return .speechCommand(try payload.decode(SpeechCommand.self))
    case EventNames.hermesWorkChanged: return .hermesWorkChanged(try payload.decode(HermesWork.self))
    case EventNames.callsChanged: return .callsChanged(try payload.decode(CallState.self))
    case EventNames.callsCommand: return .callsCommand(try payload.decode(CallCommand.self))
    case EventNames.calendarChanged: return .calendarChanged
    case EventNames.automationsChanged: return .automationsChanged
    case EventNames.automationsRunProgress: return .automationsRunProgress(try payload.decode(AutomationRunProgress.self))
    case EventNames.hermesRoomsChanged: return .hermesRoomsChanged(try payload.decode(HermesRoomView.self))
    case EventNames.hermesRoomsListChanged: return .hermesRoomsListChanged(try payload.decode(HermesRooms.self))
    case EventNames.appleCommand: return .appleCommand(try payload.decode(AppleCommand.self))
    case EventNames.locationCommand: return .locationCommand(try payload.decode(LocationCommand.self))
    case EventNames.composerInsertText: return .composerInsertText(try payload.decode(ComposerInsertText.self))
    default: return .unknown(name: name, payload: payload)
    }
  }

  /// The event's name, as the envelope carries it.
  public var name: String {
    switch self {
    case .turnStarted: return EventNames.turnStarted
    case .turnDelta: return EventNames.turnDelta
    case .turnBlocks: return EventNames.turnBlocks
    case .turnCompleted: return EventNames.turnCompleted
    case .turnFailed: return EventNames.turnFailed
    case .turnFinished: return EventNames.turnFinished
    case .chatsChanged: return EventNames.chatsChanged
    case .accountsChanged: return EventNames.accountsChanged
    case .serversChanged: return EventNames.serversChanged
    case .notesChanged: return EventNames.notesChanged
    case .channelsMessage: return EventNames.channelsMessage
    case .channelsTyping: return EventNames.channelsTyping
    case .channelsChanged: return EventNames.channelsChanged
    case .channelsAppReply: return EventNames.channelsAppReply
    case .channelsPosted: return EventNames.channelsPosted
    case .syncStatus: return EventNames.syncStatus
    case .socketHealth: return EventNames.socketHealth
    case .notifyShow: return EventNames.notifyShow
    case .routeRemap: return EventNames.routeRemap
    case .uiRequest: return EventNames.uiRequest
    case .uiSettled: return EventNames.uiSettled
    case .capabilitiesChanged: return EventNames.capabilitiesChanged
    case .modelsChanged: return EventNames.modelsChanged
    case .openUrl: return EventNames.openUrl
    case .workspaceChanged: return EventNames.workspaceChanged
    case .hermesChanged: return EventNames.hermesChanged
    case .authChanged: return EventNames.authChanged
    case .voiceChanged: return EventNames.voiceChanged
    case .terminalDisplayFile: return EventNames.terminalDisplayFile
    case .terminalChanged: return EventNames.terminalChanged
    case .settingsChanged: return EventNames.settingsChanged
    case .notificationsChanged: return EventNames.notificationsChanged
    case .notificationsAnswered: return EventNames.notificationsAnswered
    case .queueChanged: return EventNames.queueChanged
    case .messagesMerge: return EventNames.messagesMerge
    case .handoffRequested: return EventNames.handoffRequested
    case .handoffSettled: return EventNames.handoffSettled
    case .chatPromptsChanged: return EventNames.chatPromptsChanged
    case .mcpAppsEvent: return EventNames.mcpAppsEvent
    case .speechChanged: return EventNames.speechChanged
    case .speechCommand: return EventNames.speechCommand
    case .hermesWorkChanged: return EventNames.hermesWorkChanged
    case .callsChanged: return EventNames.callsChanged
    case .callsCommand: return EventNames.callsCommand
    case .calendarChanged: return EventNames.calendarChanged
    case .automationsChanged: return EventNames.automationsChanged
    case .automationsRunProgress: return EventNames.automationsRunProgress
    case .hermesRoomsChanged: return EventNames.hermesRoomsChanged
    case .hermesRoomsListChanged: return EventNames.hermesRoomsListChanged
    case .appleCommand: return EventNames.appleCommand
    case .locationCommand: return EventNames.locationCommand
    case .composerInsertText: return EventNames.composerInsertText
    case .unknown(let name, _): return name
    }
  }

  /// Whether this build's event table publishes the event with a scope; false
  /// for an unknown one. To route an event, read its envelope's `scope`.
  public var isScoped: Bool {
    switch self {
    case .turnStarted, .turnDelta, .turnBlocks, .turnCompleted, .turnFailed, .channelsMessage, .channelsTyping, .channelsAppReply, .terminalDisplayFile, .queueChanged, .messagesMerge, .chatPromptsChanged, .mcpAppsEvent, .hermesWorkChanged, .hermesRoomsChanged, .composerInsertText: return true
    default: return false
    }
  }

  /// The payload as JSON, as the envelope carries it: an empty object for an
  /// event without one.
  public func payload() throws -> JSONValue {
    switch self {
    case .turnStarted(let payload): return try JSONValue(encoding: payload)
    case .turnDelta(let payload): return try JSONValue(encoding: payload)
    case .turnBlocks(let payload): return try JSONValue(encoding: payload)
    case .turnCompleted(let payload): return try JSONValue(encoding: payload)
    case .turnFailed(let payload): return try JSONValue(encoding: payload)
    case .turnFinished(let payload): return try JSONValue(encoding: payload)
    case .chatsChanged(let payload): return try JSONValue(encoding: payload)
    case .accountsChanged(let payload): return try JSONValue(encoding: payload)
    case .serversChanged(let payload): return try JSONValue(encoding: payload)
    case .notesChanged(let payload): return try JSONValue(encoding: payload)
    case .channelsMessage(let payload): return try JSONValue(encoding: payload)
    case .channelsTyping(let payload): return try JSONValue(encoding: payload)
    case .channelsChanged: return .object([:])
    case .channelsAppReply(let payload): return try JSONValue(encoding: payload)
    case .channelsPosted(let payload): return try JSONValue(encoding: payload)
    case .syncStatus(let payload): return try JSONValue(encoding: payload)
    case .socketHealth: return .object([:])
    case .notifyShow(let payload): return try JSONValue(encoding: payload)
    case .routeRemap(let payload): return try JSONValue(encoding: payload)
    case .uiRequest(let payload): return try JSONValue(encoding: payload)
    case .uiSettled(let payload): return try JSONValue(encoding: payload)
    case .capabilitiesChanged: return .object([:])
    case .modelsChanged: return .object([:])
    case .openUrl(let payload): return try JSONValue(encoding: payload)
    case .workspaceChanged(let payload): return try JSONValue(encoding: payload)
    case .hermesChanged(let payload): return try JSONValue(encoding: payload)
    case .authChanged: return .object([:])
    case .voiceChanged(let payload): return try JSONValue(encoding: payload)
    case .terminalDisplayFile(let payload): return try JSONValue(encoding: payload)
    case .terminalChanged(let payload): return try JSONValue(encoding: payload)
    case .settingsChanged: return .object([:])
    case .notificationsChanged: return .object([:])
    case .notificationsAnswered(let payload): return try JSONValue(encoding: payload)
    case .queueChanged(let payload): return try JSONValue(encoding: payload)
    case .messagesMerge(let payload): return try JSONValue(encoding: payload)
    case .handoffRequested(let payload): return try JSONValue(encoding: payload)
    case .handoffSettled(let payload): return try JSONValue(encoding: payload)
    case .chatPromptsChanged(let payload): return try JSONValue(encoding: payload)
    case .mcpAppsEvent(let payload): return try JSONValue(encoding: payload)
    case .speechChanged(let payload): return try JSONValue(encoding: payload)
    case .speechCommand(let payload): return try JSONValue(encoding: payload)
    case .hermesWorkChanged(let payload): return try JSONValue(encoding: payload)
    case .callsChanged(let payload): return try JSONValue(encoding: payload)
    case .callsCommand(let payload): return try JSONValue(encoding: payload)
    case .calendarChanged: return .object([:])
    case .automationsChanged: return .object([:])
    case .automationsRunProgress(let payload): return try JSONValue(encoding: payload)
    case .hermesRoomsChanged(let payload): return try JSONValue(encoding: payload)
    case .hermesRoomsListChanged(let payload): return try JSONValue(encoding: payload)
    case .appleCommand(let payload): return try JSONValue(encoding: payload)
    case .locationCommand(let payload): return try JSONValue(encoding: payload)
    case .composerInsertText(let payload): return try JSONValue(encoding: payload)
    case .unknown(_, let payload): return payload
    }
  }
